\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{graphicx}
\usepackage{booktabs}

\title{Retrieval-Augmented Generation for Low-Resource Languages}
\author{N.~Osei and R.~Kowalczyk}
\date{May 2026}

\begin{document}
\maketitle
\section{Introduction}\label{introduction}
Low-resource languages remain underserved by large language models, and retrieval augmentation is the most practical lever for closing the gap without retraining. Section~\ref{sec-method} details our approach.
\begin{figure}[t]
\centering
\IfFileExists{figures/teaser.pdf}{\includegraphics[width=0.8\columnwidth]{figures/teaser.pdf}}{\rule{0.8\columnwidth}{3.2cm}}
\caption{Retrieval coverage versus model size for twelve languages.}\label{fig:teaser}
\end{figure}

\section{Background}\label{SEC:background}
We build on dense passage retrieval and on instruction-tuned generators. The retriever scores passages by inner product, and the generator conditions on the top-$k$ passages concatenated with the query.

\section{Method}\label{sec-method}
Figure~\ref{Fig:pipeline} summarises the architecture.
\begin{figure}[t]
\centering
\IfFileExists{figures/pipeline.pdf}{\includegraphics[width=0.9\columnwidth]{figures/pipeline.pdf}}{\rule{0.9\columnwidth}{3.2cm}}
\caption{The two-tower retrieval architecture with generator fusion.}\label{Fig:pipeline}
\end{figure}
The attention weight for passage $j$ and the training objective are
\begin{equation}
\alpha_j = \operatorname{softmax}(q^\top K_j / \sqrt{d}), \label{eq:attention}
\end{equation}
\begin{equation}
\mathcal{L} = \mathcal{L}_{\mathrm{gen}} + \lambda \mathcal{L}_{\mathrm{ret}}, \label{equation:objective}
\end{equation}
with the softmax normalisation and a stabilising regulariser given by
\begin{equation}
p_j = \frac{\exp(s_j)}{\sum_{l} \exp(s_l)}, \label{eq:softmax}
\end{equation}
\begin{equation}
\mathcal{R} = \|K\|_F^2 + \|q\|_2^2. \label{Eq:regularizer}
\end{equation}
The proof of convergence is deferred to Appendix~\ref{app:proof}.
Retrieval scoring uses the inner product, and the fused score combines it with the language model likelihood:
\begin{equation}
s_j = q^\top K_j, \label{eq:retrieval}
\end{equation}
\begin{equation}
S_j = s_j + \beta \log p_{\theta}(y \mid x, j). \label{eq:scoring}
\end{equation}
An auxiliary loss aligns the two towers, and the inference cost is linear in the index size:
\begin{equation}
\mathcal{L}_{\mathrm{aux}} = 1 - \cos(q, K_{+}), \label{eq:loss-aux}
\end{equation}
\begin{equation}
T = O(k \cdot N \cdot d). \label{eq:complexity}
\end{equation}

\section{Data}\label{sec:data}
We train on twelve languages spanning four families; the corpora of Table~\ref{table:datasets} total 41 billion tokens after filtering. Table~\ref{tab:languages} lists the evaluation languages.
\begin{table}[t]
\centering
\caption{Corpus statistics per language family.}\label{table:datasets}
\begin{tabular}{lrr}
\toprule
Family & Languages & Tokens (B) \\
\midrule
Bantu & 4 & 14.2 \\
Slavic & 3 & 11.8 \\
\bottomrule
\end{tabular}
\end{table}
\begin{table}[t]
\centering
\caption{Evaluation languages and their resource tiers.}\label{tab:languages}
\begin{tabular}{ll}
\toprule
Language & Tier \\
\midrule
Yoruba & low \\
Quechua & very low \\
\bottomrule
\end{tabular}
\end{table}

\section{Experiments}\label{sec:Experiments}
We fine-tune the model of Section~\ref{sec-method} for 30 epochs with AdamW. Table~\ref{tab:hyperparams} reports the hyperparameters.
\begin{table}[t]
\centering
\caption{Hyperparameters for all reported runs.}\label{tab:hyperparams}
\begin{tabular}{lr}
\toprule
Parameter & Value \\
\midrule
Learning rate & $3 \times 10^{-5}$ \\
Batch size & 256 \\
\bottomrule
\end{tabular}
\end{table}

\section{Results}\label{results-section}
Figure~\ref{figure:attention} visualises the learned attention, and Table~\ref{tab:main-results} reports the main comparison.
\begin{figure}[t]
\centering
\IfFileExists{figures/attention.pdf}{\includegraphics[width=0.75\columnwidth]{figures/attention.pdf}}{\rule{0.75\columnwidth}{3.0cm}}
\caption{Attention maps for a Yoruba query with three passages.}\label{figure:attention}
\end{figure}
\begin{table}[t]
\centering
\caption{Exact match on the evaluation suite.}\label{tab:main-results}
\begin{tabular}{lr}
\toprule
System & EM \\
\midrule
Closed-book & 31.4 \\
Ours & 46.9 \\
\bottomrule
\end{tabular}
\end{table}
Figure~\ref{fig:qualitative} shows a qualitative example.
\begin{figure}[t]
\centering
\IfFileExists{figures/qualitative.pdf}{\includegraphics[width=0.8\columnwidth]{figures/qualitative.pdf}}{\rule{0.8\columnwidth}{3.0cm}}
\caption{Retrieved passages for a code-switched query.}\label{fig:qualitative}
\end{figure}

\section{Ablations}\label{sec:ablations}
All ablations follow the training protocol of Section~\ref{sec:Experiments}.
Table~\ref{tab_ablation} ablates each component, and Figure~\ref{fig:scaling} plots the scaling behaviour.
\begin{table}[t]
\centering
\caption{Ablation results on the development set.}\label{tab_ablation}
\begin{tabular}{lr}
\toprule
Variant & EM \\
\midrule
Full model & 46.9 \\
No auxiliary loss & 44.1 \\
\bottomrule
\end{tabular}
\end{table}
\begin{figure}[t]
\centering
\IfFileExists{figures/scaling.pdf}{\includegraphics[width=0.75\columnwidth]{figures/scaling.pdf}}{\rule{0.75\columnwidth}{3.0cm}}
\caption{Exact match as a function of index size.}\label{fig:scaling}
\end{figure}
\section{Related Work}\label{sec:related}
Our setting is closest to recent work on retrieval for under-served languages, and, as motivated in Section~\ref{introduction}, we prioritise methods that require no generator retraining.
\section{Conclusion}\label{sec:conclusion}
Retrieval augmentation closes much of the low-resource gap, and the gains of Section~\ref{results-section} hold across all twelve languages.

\appendix
\section{Proof Details}\label{app:proof}
We bound the gradient of the objective in \eqref{equation:objective}. Under the regulariser of \eqref{Eq:regularizer}, the gradient satisfies
\begin{equation}
\|\nabla \mathcal{L}\| \le G \sqrt{d}, \label{eq:gradient}
\end{equation}
which yields the convergence bound
\begin{equation}
\mathbb{E}[\mathcal{L}_T] - \mathcal{L}^{*} \le \frac{G^2 d}{T}, \label{eq:bound}
\end{equation}
completing the proof sketched for \eqref{equation:objective}.
\end{document}

